    barrier = None
    for v in vals:
        is_barrier = False
        # Check if any row is fully v
        for r in range(rows):
            if all(grid[r][c] == v for c in range(cols)):
                is_barrier = True
                break
        if is_barrier:
            barrier = v
            break
        # Check if any col is fully v
        if not is_barrier:
            for c in range(cols):
                if all(grid[r][c] == v for r in range(rows)):
                    barrier = v
                    break
            if barrier:
                break

    if barrier is None:
        # Fallback: usually the least common or specific value? 
        # Or just pick one to avoid crash. 
        # Assuming at least one value forms lines in ARC structure.
        barrier = list(vals)[0]

    # 3. Identify Background (most frequent value)
    counts = {}
    for r in range(rows):
        for c in range(cols):
            counts[grid[r][c]] = counts.get(grid[r][c], 0) + 1
    bg = max(counts, key=counts.get)

    # 4. Identify Barrier Indices
    barrier_rows = [r for r in range(rows) if all(grid[r][c] == barrier for c in range(cols))]
    barrier_cols = [c for c in range(cols) if all(grid[r][c] == barrier for r in range(rows))]

    # 5. Get Segment Starts
