            cur = b + 1
        if cur < limit:
            starts.append(cur)
        return starts

    row_segs = get_starts(barrier_rows, rows)
    col_segs = get_starts(barrier_cols, cols)

    # 6. Identify Pattern Pixels (Non-background, Non-barrier)
    pattern = []
    for r in range(rows):
        for c in range(cols):
            v = grid[r][c]
            if v != barrier and v != bg:
                pattern.append((r, c, v))

    # 7. Replicate Pattern to all Segments
    out = copy.deepcopy(grid)

    for pr, pc, pv in pattern:
        # Find source segment start
